import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {LanguageProvider} from '../../src/lib/LanguageContext';import {DictionaryArticle} from '../../src/features/dictionary/DictionaryArticle';
import {DictionaryReadingNavigation} from '../../src/features/dictionary/DictionaryReadLink';import StudyCompositionSummary from '../../src/features/study/components/StudyCompositionSummary';
const id=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,params=new URLSearchParams(location.search),long=params.has('long'),empty=params.has('empty');
const blank=(n,kind,headword)=>({entry:{id:id(n),kind,headword,status:'published'},senses:[{id:id(n+100),gloss_zh_tw:'實際義項'}],relations:[],related:[],etymologies:[],learning_notes:[],inflections:[],pronunciations:[]});
const data=blank(1,'word',long?'antidisestablishmentarianism':'adore');data.entry.word_segments=[{id:id(20),text:long?'antidisestablishment':'ad',hint:long?'這是一段很長但不能拉開英文字距的中文提示':'向',relation_id:empty?null:id(30)},{id:id(21),text:long?'arianism':'ore',hint:'說話',relation_id:empty?null:id(31)}];
if(!empty){data.learning_notes=[{id:id(40),sense_id:null,kind:'core_concept',body:long?'整個單字的概念不應被自行改寫或切成不同歷史來源。原文第二句也完整保留。':'向神祈求'}];data.relations=[{id:id(30),sense_id:null,target_entry_id:id(2),target_sense_id:id(102)},{id:id(31),sense_id:null,target_entry_id:id(3),target_sense_id:id(103)}];data.related=[{id:id(2),kind:'prefix',headword:'ad-',sense_id:id(102),gloss_zh_tw:'向'},{id:id(3),kind:'root',headword:'ore',sense_id:id(103),gloss_zh_tw:'說話'}];}
data.etymologies=[{id:id(41),sense_id:null,body:'完整單字的歷史詞源，不可拆給構詞。',data_source:'Word source'}];
const prefix=blank(2,'prefix','ad-');prefix.etymologies=[{id:id(50),sense_id:null,body:'ad- 已發布的歷史詞源',data_source:'https://example.test/ad'},{id:id(51),sense_id:id(102),body:'適用連結義項的詞源'},{id:id(52),sense_id:id(999),body:'其他義項的隱藏詞源'}];
const root=blank(3,'root','ore');root.entry.status='draft';root.etymologies=[{id:id(60),sense_id:null,body:'不可洩漏的草稿詞源'}];
window.morphologyCalls=[];window.dictionaryClient={rpc:async(name,args)=>{window.morphologyCalls.push(args.entry_uuid);await new Promise(r=>setTimeout(r,15));return{data:args.entry_uuid===id(1)?data:args.entry_uuid===id(2)?prefix:root};}};
function App(){const[embedded,setEmbedded]=useState(false),[visited,setVisited]=useState('');return <LanguageProvider initialLanguage={params.get('lang')??'zh-TW'}><main className="mx-auto max-w-3xl p-4"><button onClick={()=>setEmbedded(e=>!e)}>Toggle embedded</button><output>{visited}</output><div className="my-5 text-center"><p className="text-2xl sm:text-3xl"><StudyCompositionSummary inline entryId={id(1)} front={data.entry.headword} answer="中文主答案"/></p><p className="mt-6 text-3xl sm:text-5xl">中文主答案</p></div><DictionaryReadingNavigation.Provider value={embedded?href=>setVisited(href):null}><DictionaryArticle data={data} showConnections={false}/></DictionaryReadingNavigation.Provider></main></LanguageProvider>;}createRoot(document.getElementById('root')).render(<App/>);
